import{_ as i,C as n,o as e,c as l,a2 as a,b as s,w as r,a as c,E as h,a3 as d}from"./chunks/framework.l6sz0Vgx.js";const f=JSON.parse('{"title":"AI债务周期","description":"当算力变成融资标的 — 规模定价结构证伪","frontmatter":{"title":"AI债务周期","description":"当算力变成融资标的 — 规模定价结构证伪"},"headers":[],"relativePath":"posts/econ-aidebt.md","filePath":"posts/econ-aidebt.md","lastUpdated":1791740552000}'),g={name:"posts/econ-aidebt.md"};function u(p,t,A,m,E,b){const o=n("Mermaid");return e(),l("div",null,[t[1]||(t[1]=a('<h1 id="ai债务周期-当算力变成融资标的" tabindex="-1">AI债务周期：当算力变成融资标的 <a class="header-anchor" href="#ai债务周期-当算力变成融资标的" aria-label="Permalink to &quot;AI债务周期：当算力变成融资标的&quot;">​</a></h1><blockquote><p><strong>用途：</strong> 行业分析第四篇，挂靠《股市笔记》§1.5（政策传导）与《交易流派》信用流动性逻辑。不提供个股推荐，不构成投资建议。 <strong>证据标准：</strong> 每个数字须有<strong>日期 + 口径 + 来源</strong>；凡标&quot;<strong>待核</strong>&quot;未经逐条回溯原文，引用前须复核。空方观点（Burry/Ares）与多方反驳并列，不预设立场。</p></blockquote><h2 id="运行层-从现金买单到借钱买单" tabindex="-1">运行层：从现金买单到借钱买单 <a class="header-anchor" href="#运行层-从现金买单到借钱买单" aria-label="Permalink to &quot;运行层：从现金买单到借钱买单&quot;">​</a></h2><ul><li><strong>规模：</strong> 摩根士丹利预计2026年AI相关债务发行约5700亿美元（5月底已2360亿，为去年同期四倍，Odaily 2026-08-17转引）；五大超大规模运营商今年已发债约2200亿美元（新浪2026-10-09）；Hyperscaler支出今年约7000亿、2027年或破1万亿美元；摩根大通预计到2030年AI相关累计发债4.1万亿美元（智通财经2026-09-28转引）。</li><li><strong>现金流转负：</strong> Alphabet Q2 capex 449亿、自由现金流-59亿（史上首次）；Amazon过去12月自由现金流+182亿→-76亿，2026年capex约2200亿；Meta Q2自由现金流85.5亿→7.84亿；Oracle FY2026 capex 556.6亿、自由现金流-236.9亿，评级BBB-（Odaily 2026-08-17转引）。</li><li><strong>期限错配：</strong> 钱今天花（土地/电力/GPU），收入未来多年收；Alphabet发100年期债券、250亿投资级债，Amazon两笔约540亿+250亿，Meta 250亿（Odaily 2026-08-17转引）。</li><li><strong>争夺池子：</strong> 美国2026财年赤字1.993万亿美元（CBO口径，新浪2026-10-09）；AI与政府同抢长期资本，10年期美债约5.17%、30年约5.73%（2002年来最高，ZGEO/新浪2026-10-09）；低评级AI借款收益率近11%（Volta案例），880亿美元低评级AI借款已入市（高盛口径）。</li></ul>',4)),(e(),s(d,null,{default:r(()=>[h(o,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22AI%E6%94%AF%E5%87%BA%3Cbr%2F%3E7000%E4%BA%BF%22%5D%20--%3E%20B%5B%22%E5%80%BA%E5%8A%A1%E8%9E%8D%E8%B5%84%3Cbr%2F%3E5700%E4%BA%BF%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E4%BF%9D%E9%99%A9%E7%A7%81%E5%8B%9F%3Cbr%2F%3E%E6%8E%A5%E7%9B%98%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E8%AF%81%E4%BC%AA%E7%82%B9%3Cbr%2F%3E%E6%94%B6%E5%85%A5%E6%88%96%E5%88%A9%E7%8E%87%22%5D%0A%20%20%20%20D%20-.%20%22%E6%94%B6%E5%85%A5%E4%B8%8D%E5%8F%8A%E9%A2%84%E6%9C%9F%22%20.-%3E%20E%5B%22%E8%BF%9E%E9%94%81%3Cbr%2F%3E%E6%8B%85%E4%BF%9D%E8%A7%A6%E5%8F%91%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="定价层-从需求交易到资本回报率交易" tabindex="-1">定价层：从需求交易到资本回报率交易 <a class="header-anchor" href="#定价层-从需求交易到资本回报率交易" aria-label="Permalink to &quot;定价层：从需求交易到资本回报率交易&quot;">​</a></h2><ul><li><strong>叙事切换：</strong> 市场从&quot;需求交易&quot;进入&quot;资本回报率交易&quot;（Odaily 2026-08-17）：问题从&quot;能建多少算力&quot;变成&quot;算力能否自我偿付&quot;（本金+利息+电力运维+折旧）。</li><li><strong>折旧争议：</strong> Burry称超大规模厂商把芯片寿命拉到4–6年、2026–2028或少计约1760亿美元折旧，Oracle 2028年盈利或高估27%（智通财经2026-09-28转引其帖文）；英伟达七页备忘录反驳称4–6年合理；美光称存储需求到2028年超供给（反驳需求夸大论）。</li><li><strong>残值：</strong> H100三年残值降51%（Ares图表，Burry转引，待核）；旧GPU租金是&quot;贬值快于偿还&quot;的先行指标；CoreWeave近全价续签旧芯片是反例。</li><li><strong>期限错配：</strong> 2026年购置硬件在债务到期时或落后两代，租金下滑即覆盖不了本息——这是期限错配的数学本质。</li></ul><h2 id="结构层-融资网络与接盘方" tabindex="-1">结构层：融资网络与接盘方 <a class="header-anchor" href="#结构层-融资网络与接盘方" aria-label="Permalink to &quot;结构层：融资网络与接盘方&quot;">​</a></h2><ul><li><strong>网络：</strong> Ares 2026秋季另类信贷通讯：过去12个月26笔约5730亿美元，横跨公司债/建设贷款/租赁/GPU抵押/担保；Meta/Oracle/微软/亚马逊/谷歌/英伟达/OpenAI/Anthropic同网不同身份（借款人/租户/供应商/担保人），前提全是&quot;AI支出持续增长&quot;（智通财经2026-09-28转引）。</li><li><strong>接盘：</strong> 美国与百慕大保险浮存金超10万亿美元（Burry口径，待核）；Ares口径美国保险投资资产9万亿美元；Meta埃尔帕索140亿美元园区火险上限仅4.5亿（~3%），风险从保单转向租约担保条款。</li><li><strong>新结构：</strong> SPV表外租赁（甲骨文模式）、私募信贷（Apollo/Blackstone/PIMCO枢纽）、博通为OpenAI超500亿美元融资牵头+担保（VT Markets 2026-10-08转引）；供应商变担保方：订单锁定 vs 双重冲击（失单+代偿）。</li><li><strong>租赁锁定：</strong> 五家未来租赁付款约1.16万亿美元（微软3291亿/Meta 2790亿/Oracle 2600亿，Odaily 2026-08-17转引）——需求在是收入基础，需求掉头是固定成本。</li><li><strong>传导：</strong> Ares警告的2000年&quot;供应商融资&quot;类比：支出节奏一变，担保在担保人最弱时触发。</li></ul><h2 id="证伪层" tabindex="-1">证伪层 <a class="header-anchor" href="#证伪层" aria-label="Permalink to &quot;证伪层&quot;">​</a></h2><ul><li><strong>多方证伪（泡沫不破）：</strong> 2028年规模化盈利窗口兑现（ZGEO）、收入覆盖债务、推理与应用变现加速、存储需求到2028年超供给（美光）。</li><li><strong>空方证伪（泡沫破）：</strong> 利率继续上行（Dalio临界点：利率起效之时）、收入不及预期致董事会挪资本、旧GPU租金下行、CDS走阔、博通/OpenAI交易担保比例超预期。</li><li><strong>Dalio框架：</strong> 债务+利率+集中度=经典泡沫三件套；10–15条非相关回报流、大失序时期（福布斯CEO大会2026-10-07，21财经/澎湃转引）；政府与科技同发债的&quot;心肌梗死&quot;（达利欧，Julia La Roche访谈转引）。</li><li><strong>跟踪项：</strong> AI债务发行月度、10年/30年美债、旧GPU租金、相关CDS、博通12月财报担保披露、头部capex指引。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>Odaily AI融资周期（2026-08-17）：<a href="https://www.odaily.news/zh-CN/post/5212537" target="_blank" rel="noreferrer">https://www.odaily.news/zh-CN/post/5212537</a></li><li>智通财经Burry/Ares（2026-09-28）：<a href="https://www.zhitongcaijing.com/content/detail/1501589.html" target="_blank" rel="noreferrer">https://www.zhitongcaijing.com/content/detail/1501589.html</a></li><li>新浪资本争夺战（2026-10-09）：<a href="https://k.sina.cn/article_5952915705_162d248f906703q7ku.html" target="_blank" rel="noreferrer">https://k.sina.cn/article_5952915705_162d248f906703q7ku.html</a></li><li>ZGEO压力测试（2026-10-09）：<a href="https://zgeo.net/news/ai-capex-high-interest-debt-geo" target="_blank" rel="noreferrer">https://zgeo.net/news/ai-capex-high-interest-debt-geo</a></li><li>21财经Dalio警告（2026-10-09）：<a href="https://www.21jingji.com/article/20261009/herald/6e01d4b56f7c9bbd12f4fd31fac58555.html" target="_blank" rel="noreferrer">https://www.21jingji.com/article/20261009/herald/6e01d4b56f7c9bbd12f4fd31fac58555.html</a></li><li>澎湃AI泡沫（2026-10-08）：<a href="https://m.thepaper.cn/newsDetail_forward_34212160" target="_blank" rel="noreferrer">https://m.thepaper.cn/newsDetail_forward_34212160</a></li><li>VT Markets信贷额度（2026-10-08）：<a href="https://www.vtmarkets.com/cn-asia/opinion/the-ai-boom-just-opened-a-credit-line/" target="_blank" rel="noreferrer">https://www.vtmarkets.com/cn-asia/opinion/the-ai-boom-just-opened-a-credit-line/</a></li><li>BusinessTimes Dalio原文（2026-10-07）：<a href="https://www.businesstimes.com.sg/zh-hans/companies-markets/ai-bubble-may-burst-soon-amid-financing-concentration-rising-rates-ray-dalio" target="_blank" rel="noreferrer">https://www.businesstimes.com.sg/zh-hans/companies-markets/ai-bubble-may-burst-soon-amid-financing-concentration-rising-rates-ray-dalio</a></li></ul>',8))])}const w=i(g,[["render",u]]);export{f as __pageData,w as default};
